package com.cloudticket.order.api;
import com.cloudticket.common.security.RequireInternalToken; import com.cloudticket.order.persistence.OrderRepository; import java.util.Map; import org.springframework.web.bind.annotation.*;
@RestController @RequireInternalToken @RequestMapping("/api/internal/orders") public class InternalOrderEligibilityController { private final OrderRepository orders; public InternalOrderEligibilityController(OrderRepository o){orders=o;} @GetMapping("/users/{userId}/activities/{activityId}/paid") public Map<String,Object> paid(@PathVariable String userId,@PathVariable String activityId){var page=orders.pageForUser(userId,0,100);long count=page.items().stream().filter(x->activityId.equals(x.getActivityId())&&"PAID".equals(x.getStatus())).count();return Map.of("eligible",count>0,"count",count);} }
